const req = $('When Executed by Another Workflow').first().json;
const draft = $input.first().json;
if (!draft.id) throw new Error('draft_not_found');
if (Number(req.base_version) !== Number(draft.current_version)) throw new Error('stale_version: version mới nhất là ' + draft.current_version);
if (['approved', 'publishing', 'published', 'partial_failure'].includes(draft.status)) throw new Error('approved_version_is_immutable');
if (!String(req.feedback || '').trim()) throw new Error('missing_information: feedback');
const parse = (v, f, fb) => { if (v === undefined || v === null || v === '') return fb; if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { throw new Error('invalid_json: ' + f); } };
const website = parse(req.website_payload, 'website_payload', null);
const threads = parse(req.threads_payload, 'threads_payload', null);
if (!website || typeof website !== 'object' || !String(website.title || '').trim()) throw new Error('invalid_payload: website_payload cần có title');
if (!threads || typeof threads !== 'object' || !String(threads.text || threads.content || '').trim()) throw new Error('invalid_payload: threads_payload cần có text');
if (String(threads.text || threads.content).length > 500) throw new Error('threads_text_too_long: tối đa 500 ký tự');
const images = parse(req.images, 'images', []);
const sources = parse(req.sources, 'sources', []);
if (!Array.isArray(images) || !Array.isArray(sources)) throw new Error('invalid_json: images và sources phải là array');
return [{ json: { ...req, next_version: Number(draft.current_version) + 1, website_payload: website, threads_payload: threads, images, sources } }];

const draft = $input.first().json;
const v = $('Create Revised Version').first().json;
return [{ json: { status: 'in_review', draft: { ...draft, draft_id: draft.id, version: v.version, website_payload: v.website_payload, threads_payload: v.threads_payload, images: v.images, sources: v.sources } } }];
